// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(address caller, uint256 wagerLimit) public {
        vm.assume(caller != address(this)); // not owner
        vm.prank(caller);
        // Call AdjustBetAmounts: reference reverts (onlyOwner) but mutant doesn't change state
        // We expect that openToPublic remains false regardless
        c.AdjustBetAmounts(wagerLimit);
        // The rule: after AdjustBetAmounts (even if reverted in reference), openToPublic is false
        // Use try/catch to handle revert
        bool reverted = false;
        try c.AdjustBetAmounts(wagerLimit) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // After call (or attempted call), openToPublic should be false
        // Use a separate call to check openToPublic (there's no getter, but the contract has a public variable? Actually openToPublic is public, so we can read it)
        // The reference contract: openToPublic is public, so c.openToPublic() exists
        assertTrue(!c.openToPublic());
    }
}

