pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address player, uint256 amount) public {
        // Restrict amount to avoid overflow and ensure it's reasonable
        amount = bound(amount, 1, 1e30);
        vm.assume(player != address(0) && player != address(this));

        // Open the contract to public
        c.OpenToThePublic();

        // Have the player make a wager first (to create a non-zero wager entry)
        vm.deal(player, amount);
        vm.prank(player);
        c.wager{value: amount}();

        // Now call AdjustBetAmounts
        c.AdjustBetAmounts(amount);

        // The invariant: after AdjustBetAmounts, calling wager again with the same player should revert
        // because the wager amount is already > 0 (in reference) or can be > 0 (in buggy)
        // In the reference, require(wagers[msg.sender] == 0) would revert
        // In the buggy version, require(wagers[msg.sender] > 0) would pass and then overwrite
        vm.deal(player, amount);
        vm.prank(player);
        (bool success,) = address(c).call{value: amount}(abi.encodeWithSignature("wager()"));
        assertTrue(!success, "wager should revert for player with existing wager");
    }
}

