pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(address wagerAddr, uint256 wagerAmount) public {
        // Ensure wagerAmount is nonzero to avoid trivial revert
        vm.assume(wagerAmount > 0);

        // Call AdjustBetAmounts to set bet limit (but the bug is in isOpenToPublic modifier)
        c.AdjustBetAmounts(wagerAmount);

        // Try to call wager() as a different user
        vm.prank(wagerAddr);
        (bool success, ) = address(c).call{value: wagerAmount}(abi.encodeWithSignature("wager()"));

        // Rule: wager should revert (fail) if openToPublic is false (default), succeed otherwise
        // In the reference, openToPublic is false, so success == false
        // In the mutant, openToPublic is false, but modifier uses !openToPublic, so it passes -> success == true
        assertTrue(!success, "wager should revert when openToPublic is false");
    }
}

