pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 betLimit, uint256 difficulty, address player) public {
        vm.assume(player != address(0) && player != address(this));
        vm.assume(betLimit > 0 && betLimit < 1e30);
        vm.assume(difficulty >= 2 && difficulty < 1e10);

        // Open to public and set difficulty
        c.OpenToThePublic();
        c.AdjustDifficulty(difficulty);
        c.AdjustBetAmounts(betLimit);

        // Player wagers
        vm.deal(player, betLimit);
        vm.prank(player);
        c.wager{value: betLimit}();

        // Check that play() result depends on hash as expected
        // We need a block delay for play to be valid
        vm.roll(block.number + 1);

        // Compute the expected winning condition based on original logic
        uint256 blockNumber = block.number - 1;
        uint256 randomSeed = 0; // assume default
        uint256 winningNumber = uint256(keccak256(abi.encodePacked(blockhash(blockNumber), player, randomSeed))) % difficulty + 1;
        bool expectedWin = (winningNumber == difficulty / 2);

        uint256 balanceBefore = address(this).balance;

        vm.prank(player);
        c.play();

        uint256 balanceAfter = address(this).balance;

        // The rule: After AdjustBetAmounts, the play function's behavior is determined by expectedWin
        // If expectedWin, balance decreases by half (payout to winner); if not, balance stays same
        if (expectedWin) {
            assertTrue(balanceAfter <= balanceBefore - (address(this).balance / 2) * 2);
        } else {
            assertTrue(balanceAfter == balanceBefore - (betLimit / 2));
        }
    }
}

