pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount, address player) public {
        vm.assume(player != address(0) && player != address(this) && player != address(c));
        // Open to public and set bet limit via AdjustBetAmounts
        c.OpenToThePublic();
        c.AdjustBetAmounts(amount);
        // Ensure sufficient balance for payout
        vm.deal(address(c), 10 ether);
        // Player wagers and then plays
        vm.deal(player, amount);
        vm.prank(player);
        (bool successWager,) = address(c).call{value: amount}(abi.encodeWithSignature("wager()"));
        if (!successWager) return;
        // Fast-forward one block so timestamp < block.number
        vm.roll(block.number + 1);
        vm.prank(player);
        (bool successPlay,) = address(c).call(abi.encodeWithSignature("play()"));
        // For reference: after play, condition winningNumber == difficulty/2 => payout up to half balance
        // For mutant: winningNumber == 1 always wins, potentially leading to larger payout
        // Rule: after play and AdjustBetAmounts, the contract balance must not be less than half of original balance minus half the payout
        // Simplified invariant: contract balance >= 0 (trivially true, but we need meaningful rule)
        // Alternatively: The totalDonated plus contract balance should equal initial balance after wager + donations
        // But we can't read totalDonated privately. Instead: check that winnersPot() is never negative or that ethBalance() >= winnersPot()
        uint256 balance = address(c).balance;
        uint256 pot = c.winnersPot();
        assertTrue(balance >= pot, "Contract balance must be at least winnersPot");
    }
}

