pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(uint256 betLimitValue, address player) public {
        // Ensure player is a real person (tx.origin == msg.sender) and not the zero address
        vm.assume(player != address(0));
        // Open to public
        c.OpenToThePublic();
        // Set difficulty to 2 so that difficulty/2 == 1 (meaning winning if winningNumber == 1)
        c.AdjustDifficulty(2);
        // Set bet limit via the parameter
        c.AdjustBetAmounts(betLimitValue);
        // Fund the player with enough ETH
        vm.deal(player, betLimitValue);
        // Player makes a wager
        vm.startPrank(player, player);
        c.wager{value: betLimitValue}();
        // Move to next block so timestamp differs
        vm.roll(block.number + 1);
        // Record balance before play
        uint256 balanceBefore = address(c).balance;
        // Player plays
        c.play();
        // Record balance after play
        uint256 balanceAfter = address(c).balance;
        vm.stopPrank();
        // The reference contract pays out exactly half the contract balance when winningNumber == difficulty/2 (=1).
        // After play, the contract balance must be either unchanged (if lost) or reduced by half (if won).
        // The mutant always pays out half on win condition (winningNumber == 1) regardless of actual difficulty.
        // Since difficulty is 2, winningNumber == 1 is equivalent to the original condition.
        // However, the general property: after play, the balance change is either 0 or exactly half.
        // But that's not enough to catch the mutant. Instead, note that the mutant always wins when winningNumber == 1.
        // The original contract sometimes loses even if winningNumber == 1 (if difficulty/2 != 1).
        // To force a difference, set difficulty to 4, so difficulty/2 = 2. Then winningNumber == 1 is NOT a win in original, but IS in mutant.
        // Reset contract and set difficulty to 4.
        c = new C(address(this), 0);
        c.OpenToThePublic();
        c.AdjustDifficulty(4); // difficulty/2 = 2
        c.AdjustBetAmounts(betLimitValue);
        vm.deal(player, betLimitValue);
        vm.startPrank(player, player);
        c.wager{value: betLimitValue}();
        vm.roll(block.number + 1);
        uint256 balanceBefore2 = address(c).balance;
        c.play();
        uint256 balanceAfter2 = address(c).balance;
        vm.stopPrank();
        // In the original, winningNumber == 1 should cause a lose (since difficulty/2=2, and winningNumber !=2), so balance should decrease by betLimit/2 (sent to whale).
        // In mutant, winningNumber == 1 triggers payout, so balance decreases by half.
        // Check that the balance change is consistent with original logic.
        // The original: if winningNumber == 1, it goes to loseWager (pays betLimit/2 to whale). So balance decreases by exactly betLimit/2.
        // But to capture this generally: after play, if the wager was placed, the balance change is either 0 (if win and payout received) or betLimit/2 (if lose).
        // Actually, when winning, the player gets half the balance, so balance reduces by exactly that amount.
        // For the original with difficulty=4, winningNumber==1 leads to lose, so balance decreases by betLimit/2.
        // For the mutant, winningNumber==1 leads to win, so balance decreases by balanceBefore2/2.
        // We can check that balanceAfter2 == balanceBefore2 - betLimit/2 (original behavior).
        // But betLimit/2 may not be integer if betLimit is odd. Use safe check.
        // General rule: For any wager, after play the contract balance either stays the same (if win) or decreases by exactly betLimit/2 (if lose).
        // However, that's also true in mutant for the case where winningNumber !=1.
        // To distinguish, we need to use the fact that in mutant, a win is determined by winningNumber==1, while original uses winningNumber==difficulty/2.
        // The difference is that when difficulty is not 2, the sets of winning numbers differ.
        // So we can set difficulty to a value such that 1 != difficulty/2, and then the original will always lose when winningNumber==1, but mutant wins.
        // This is already done with difficulty=4 above.
        // The property: after play, the balance change is exactly betLimit/2 (the loss amount) because original loses.
        // Mutant would give a different change (payout half the balance).
        assertTrue(balanceAfter2 == balanceBefore2 - betLimitValue/2, "Expected loss of betLimit/2");
    }
}

