pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 wagerAmount, uint256 newBetLimit) public {
        vm.assume(newBetLimit > 0 && newBetLimit <= address(this).balance);
        vm.assume(wagerAmount == newBetLimit);
        // Open the contract to public
        c.OpenToThePublic();
        // Fund the contract enough for the wager donation
        vm.deal(address(this), newBetLimit);
        // Make a wager to become a player
        c.wager{value: wagerAmount}();
        // Play to trigger the donation from loseWager
        c.play();
        // Record balance before AdjustBetAmounts
        uint256 balanceBefore = address(c).balance;
        // Call AdjustBetAmounts
        c.AdjustBetAmounts(newBetLimit);
        // Record balance after
        uint256 balanceAfter = address(c).balance;
        // The contract's balance should not have decreased by more than the amount that could be donated in donate()
        // donate() sends msg.value or msg.value+1 to whale; the donated amount is totalDonated change
        // But we cannot directly observe totalDonated, so we use the rule that balance after cannot be less than balanceBefore minus (msg.value+1) if donate were called
        // However, the reference contract's donate() sends exactly msg.value, so balanceAfter >= balanceBefore - (msg.value) for any call
        // For the mutant, donate() sends msg.value+1, so balanceAfter >= balanceBefore - (msg.value+1)
        // The difference is that the mutant can reduce balance by one more wei
        // But we need a rule that the reference always satisfies and the mutant breaks
        // The key is that after any sequence ending with AdjustBetAmounts, the balance must be at least balanceBefore - newBetLimit (since donate() could have been called with newBetLimit)
        // Actually, we want a rule that is always true for reference but false for mutant
        // Consider: if we call donate with value = newBetLimit after AdjustBetAmounts, the reference would have balance >= balanceBefore - newBetLimit
        // But the rule that the reference satisfies is: donate() does not reduce balance by more than msg.value
        // For mutant, it reduces by msg.value+1
        // So we can test: after a donate call with a specific value, the balance is at least initialBalance - value for reference, but mutant could have balance less
        // Let's use a simpler approach: call donate and then check that balance decreased by exactly msg.value
        uint256 donateAmount = newBetLimit;
        vm.deal(address(this), donateAmount);
        uint256 balanceBeforeDonate = address(c).balance;
        c.donate{value: donateAmount}();
        uint256 balanceAfterDonate = address(c).balance;
        // For reference, balanceAfterDonate == balanceBeforeDonate - donateAmount (since donateToWhale does not return anything)
        // For mutant, balanceAfterDonate == balanceBeforeDonate - (donateAmount + 1)
        // So the rule: balanceAfterDonate == balanceBeforeDonate - donateAmount
        assertTrue(balanceAfterDonate == balanceBeforeDonate - donateAmount);
    }
}

